#!/usr/bin/env bash
# Creates any missing Flutter platform folders and applies the small native
# patches this app needs (permissions, minimum OS versions).
# Usage: tools/setup_platforms.sh [android,ios,web,windows,macos,linux]
set -euo pipefail

PLATFORMS="${1:-android,ios,web,windows,macos,linux}"

missing=0
for p in ${PLATFORMS//,/ }; do
  [ -d "$p" ] || missing=1
done
if [ "$missing" = 1 ]; then
  flutter create --project-name penumbra --org dev.penumbra --platforms="$PLATFORMS" .
  rm -f test/widget_test.dart
fi

# Podfiles are generated by `flutter pub get` once the plugins are resolved.
if [ -d ios ] || [ -d macos ]; then
  flutter pub get
fi

patch_podfile() {
  # $1 = Podfile, $2 = replacement `platform` line
  if [ -f "$1" ]; then
    sed -i.bak -E "s/^#? *platform :(ios|osx), .*/$2/" "$1"
    rm -f "$1.bak"
  else
    echo "warning: $1 not found, skipping deployment target patch"
  fi
}

# ---- Android: minSdk 24 (ML Kit), legacy storage permission for API <= 28 ----
if [ -d android ]; then
  gradle="$(ls android/app/build.gradle.kts android/app/build.gradle 2>/dev/null | head -1 || true)"
  if [ -n "$gradle" ]; then
    sed -i.bak -E 's/minSdk = flutter\.minSdkVersion/minSdk = 24/; s/minSdkVersion flutter\.minSdkVersion/minSdkVersion 24/' "$gradle"
    rm -f "$gradle.bak"
  fi
  manifest=android/app/src/main/AndroidManifest.xml
  if ! grep -q WRITE_EXTERNAL_STORAGE "$manifest"; then
    sed -i.bak 's|<application|<uses-permission android:name="android.permission.WRITE_EXTERNAL_STORAGE" android:maxSdkVersion="28"/>\n    <application|' "$manifest"
    rm -f "$manifest.bak"
  fi
fi

# ---- iOS: ML Kit needs iOS 15.5+, usage descriptions for photos/camera ----
if [ -d ios ]; then
  patch_podfile ios/Podfile "platform :ios, '15.5'"
  if [ -x /usr/libexec/PlistBuddy ]; then
    plist=ios/Runner/Info.plist
    set_key() {
      /usr/libexec/PlistBuddy -c "Delete :$1" "$plist" 2>/dev/null || true
      /usr/libexec/PlistBuddy -c "Add :$1 string $2" "$plist"
    }
    set_key NSPhotoLibraryUsageDescription "Open photos to edit them."
    set_key NSPhotoLibraryAddUsageDescription "Save your edited photos."
    set_key NSCameraUsageDescription "Take photos to edit."
  fi
fi

# ---- macOS: file open/save dialogs need the user-selected entitlement ----
if [ -d macos ]; then
  patch_podfile macos/Podfile "platform :osx, '11.0'"
  if [ -x /usr/libexec/PlistBuddy ]; then
    for f in macos/Runner/DebugProfile.entitlements macos/Runner/Release.entitlements; do
      [ -f "$f" ] || continue
      /usr/libexec/PlistBuddy -c "Delete :com.apple.security.files.user-selected.read-write" "$f" 2>/dev/null || true
      /usr/libexec/PlistBuddy -c "Add :com.apple.security.files.user-selected.read-write bool true" "$f"
    done
  fi
fi

# ---- App name, description and icon (replaces the default Flutter ones) ----
DESC="Non-destructive photo editor with 36 tools, from curves and lens blur to film looks. Opens JPEG, PNG, TIFF and DNG/RAW."

if [ -f android/app/src/main/AndroidManifest.xml ]; then
  sed -i.bak -E 's/android:label="[^"]*"/android:label="Penumbra"/' android/app/src/main/AndroidManifest.xml
  rm -f android/app/src/main/AndroidManifest.xml.bak
fi

if [ -d ios ] && [ -x /usr/libexec/PlistBuddy ]; then
  for k in CFBundleDisplayName CFBundleName; do
    /usr/libexec/PlistBuddy -c "Delete :$k" ios/Runner/Info.plist 2>/dev/null || true
    /usr/libexec/PlistBuddy -c "Add :$k string Penumbra" ios/Runner/Info.plist
  done
fi

if [ -f web/index.html ]; then
  sed -i.bak -E \
    -e "s|<meta name=\"description\" content=\"[^\"]*\">|<meta name=\"description\" content=\"$DESC\">|" \
    -e 's|<title>[^<]*</title>|<title>Penumbra</title>|' \
    -e 's|(name="apple-mobile-web-app-title" content=")[^"]*"|\1Penumbra"|' web/index.html
  rm -f web/index.html.bak
fi
if [ -f web/manifest.json ]; then
  sed -i.bak -E \
    -e 's|("name": )"[^"]*"|\1"Penumbra"|' \
    -e 's|("short_name": )"[^"]*"|\1"Penumbra"|' \
    -e "s|(\"description\": )\"[^\"]*\"|\1\"$DESC\"|" web/manifest.json
  rm -f web/manifest.json.bak
fi

[ -f windows/runner/main.cpp ] && sed -i.bak 's/L"penumbra"/L"Penumbra"/' windows/runner/main.cpp && rm -f windows/runner/main.cpp.bak
[ -f linux/runner/my_application.cc ] && sed -i.bak 's/"penumbra"/"Penumbra"/g' linux/runner/my_application.cc && rm -f linux/runner/my_application.cc.bak

# Launcher icons for every platform folder that exists (needs the PNG masters
# in assets/icon; regenerate them from the SVG geometry with tools/make_icons.py).
# The config is generated on the fly so flutter_launcher_icons only touches
# platforms that are actually present (it fails hard on a missing android/ dir).
ICON_CFG="$(mktemp "${TMPDIR:-/tmp}/launcher_icons.XXXXXX")"
trap 'rm -f "$ICON_CFG"' EXIT
{
  echo "flutter_launcher_icons:"
  echo "  image_path: assets/icon/icon.png"
  if [ -d android ]; then
    echo "  android: true"
    echo "  adaptive_icon_background: \"#0E1F24\""
    echo "  adaptive_icon_foreground: assets/icon/icon_foreground.png"
  fi
  if [ -d ios ]; then
    echo "  ios: true"
    echo "  remove_alpha_ios: true"
  fi
  if [ -d web ]; then
    echo "  web:"
    echo "    generate: true"
    echo "    image_path: assets/icon/icon.png"
    echo "    background_color: \"#091215\""
    echo "    theme_color: \"#4DB6AC\""
  fi
  if [ -d windows ]; then
    echo "  windows:"
    echo "    generate: true"
    echo "    image_path: assets/icon/icon.png"
    echo "    icon_size: 256"
  fi
  if [ -d macos ]; then
    echo "  macos:"
    echo "    generate: true"
    echo "    image_path: assets/icon/icon.png"
  fi
} > "$ICON_CFG"

flutter pub get
if [ -d android ] || [ -d ios ] || [ -d web ] || [ -d windows ] || [ -d macos ]; then
  dart run flutter_launcher_icons -f "$ICON_CFG"
fi

echo "Platforms ready: $PLATFORMS"
